INSERT INTO companies (name, slug, description, website, email, phone, location, province, district) VALUES
('Rwanda Development Board', 'rwanda-development-board', 'Rwanda Development Board (RDB) is a government agency responsible for coordinating and accelerating Rwanda''s economic development by promoting investments and enabling the private sector.', 'https://rdb.rw', 'info@rdb.rw', '+250788883000', 'Kigali City', 'Kigali', 'Gasabo'),
('Bank of Kigali', 'bank-of-kigali', 'Bank of Kigali is Rwanda''s largest financial institution, offering a full range of banking services to individuals, businesses, and government entities across the country.', 'https://bankofkigali.com', 'info@bk.rw', '+250788884000', 'Kigali City', 'Kigali', 'Nyarugenge'),
('Marriott Hotel Kigali', 'marriott-hotel-kigali', 'Marriott Hotel Kigali offers world-class hospitality services in the heart of Rwanda''s capital, combining international standards with Rwandan warmth and culture.', 'https://marriott.com', 'reservations.kigali@marriott.com', '+250788885000', 'Kigali City', 'Kigali', 'Gasabo'),
('Rwanda National Police', 'rwanda-national-police', 'Rwanda National Police is responsible for maintaining law and order, preventing and combating crime, and ensuring public safety throughout Rwanda.', 'https://police.gov.rw', 'info@police.gov.rw', '+250788886000', 'Kigali City', 'Kigali', 'Nyarugenge'),
('MTN Rwanda', 'mtn-rwanda', 'MTN Rwanda is a leading telecommunications company providing mobile, internet, and digital solutions to millions of customers across Rwanda.', 'https://mtn.rw', 'info@mtn.rw', '+250788887000', 'Kigali City', 'Kigali', 'Gasabo'),
('SOS Children''s Villages Rwanda', 'sos-children-villages-rwanda', 'SOS Children''s Villages is an international non-profit organization dedicated to providing family-based care and education for children who have lost parental care.', 'https://sos-rwanda.org', 'info@sos-rwanda.org', '+250788888000', 'Kigali City', 'Kigali', 'Kicukiro'),
('Rwanda Agricultural Board', 'rwanda-agricultural-board', 'RAB is a government institution mandated to transform Rwanda''s agriculture through research, technology transfer, and quality assurance services.', 'https://rab.gov.rw', 'info@rab.gov.rw', '+250788889000', 'Huye', 'Southern', 'Huye'),
('Rwanda Information Society Authority', 'rwanda-information-society-authority', 'RISA drives Rwanda''s digital transformation agenda, managing government IT infrastructure and promoting ICT innovation across the country.', 'https://risa.gov.rw', 'info@risa.gov.rw', '+250788890000', 'Kigali City', 'Kigali', 'Gasabo');
INSERT INTO jobs (company_id, category_id, title, slug, description, responsibilities, requirements, qualifications, benefits, province, district, location, employment_type, experience_level, education_level, salary_min, salary_max, application_deadline, is_featured, status) VALUES
(1, 1, 'Senior Software Developer', 'senior-software-developer-rdb', 'We are looking for a talented Senior Software Developer to join our Digital Innovation team. You will be responsible for designing, developing, and maintaining web applications that support Rwanda''s economic development initiatives.', 'Design and develop scalable web applications\nLead technical architecture decisions\nMentor junior developers\nConduct code reviews\nCollaborate with cross-functional teams\nParticipate in agile ceremonies', '5+ years of software development experience\nProficiency in PHP, JavaScript, Python\nExperience with MySQL and PostgreSQL\nKnowledge of cloud services (AWS/Azure)\nStrong problem-solving skills', 'Bachelor''s degree in Computer Science or related field\nProfessional certifications are a plus\nExperience with government projects preferred', 'Competitive salary\nHealth insurance\nAnnual leave\nProfessional development opportunities\nModern work environment', 'Kigali', 'Gasabo', 'Kimihurura', 'Full-time', '5+ years', 'Bachelor\'s Degree', 800000, 1500000, '2026-08-30', 1, 'published'),
(2, 4, 'Financial Analyst', 'financial-analyst-bk', 'Bank of Kigali is seeking a skilled Financial Analyst to join our Risk Management department. The ideal candidate will analyze financial data, prepare reports, and support strategic decision-making.', 'Analyze financial statements and market trends\nPrepare monthly financial reports\nEvaluate investment opportunities\nMonitor risk indicators\nSupport budgeting and forecasting\nCollaborate with management on financial strategy', '3+ years of financial analysis experience\nAdvanced Excel and financial modeling skills\nKnowledge of Rwandan financial regulations\nStrong analytical and communication skills', 'Bachelor''s degree in Finance, Economics, or Accounting\nCFA or ACCA certification is an advantage\nMBA preferred', 'Competitive salary\nPerformance bonuses\nMedical insurance\nPension scheme\nTraining opportunities', 'Kigali', 'Nyarugenge', 'City Center', 'Full-time', '3+ years', 'Bachelor\'s Degree', 600000, 1200000, '2026-08-15', 1, 'published'),
(3, 9, 'Front Office Manager', 'front-office-manager-marriott', 'Marriott Hotel Kigali is looking for an experienced Front Office Manager to oversee daily front desk operations and ensure exceptional guest experiences.', 'Manage front desk operations and staff\nHandle guest complaints and escalations\nOversee reservations and check-in/check-out processes\nTrain and supervise front office team\nEnsure compliance with brand standards\nPrepare daily operations reports', '4+ years of hospitality front office experience\nStrong leadership and communication skills\nProficiency in hotel management systems\nExcellent problem-solving abilities', 'Bachelor''s degree in Hospitality Management\nMarriott brand experience preferred\nMulti-language skills are a plus', 'Competitive salary\nMeal allowances\nUniform provided\nCareer advancement opportunities\nStaff discounts', 'Kigali', 'Gasabo', 'Kimihurura', 'Full-time', '4+ years', 'Bachelor\'s Degree', 500000, 900000, '2026-09-01', 0, 'published'),
(4, 18, 'Investigation Officer', 'investigation-officer-rnp', 'Rwanda National Police is recruiting Investigation Officers to join our Criminal Investigation Department. This role involves conducting thorough investigations and ensuring justice is served.', 'Conduct criminal investigations\nGather and analyze evidence\nInterview witnesses and suspects\nPrepare investigation reports\nCollaborate with prosecutors\nMaintain case files and records', 'Bachelor''s degree in Criminology, Law, or related field\nStrong analytical and observation skills\nGood physical fitness\nClean criminal record\nWillingness to work irregular hours', 'Bachelor''s degree in relevant field\nPolice academy training preferred\nKnowledge of Rwandan laws and regulations', 'Government salary scale\nHousing allowance\nMedical coverage\nPension benefits\nCareer development', 'Kigali', 'Nyarugenge', 'Kacyiru', 'Full-time', '2+ years', 'Bachelor\'s Degree', 400000, 700000, '2026-08-20', 1, 'published'),
(5, 19, 'Network Engineer', 'network-engineer-mtn', 'MTN Rwanda is seeking a skilled Network Engineer to design, implement, and maintain our telecommunications network infrastructure across the country.', 'Design and implement network solutions\nMonitor network performance and uptime\nTroubleshoot network issues\nPerform routine maintenance and upgrades\nDocument network configurations\nSupport new technology rollouts', '3+ years of network engineering experience\nCCNA/CCNP certification\nExperience with Huawei or Ericsson equipment\nStrong TCP/IP and routing knowledge\nLinux administration skills', 'Bachelor''s degree in Telecommunications or IT\nCisco certifications required\n5G experience is a plus', 'Competitive salary\nInternet allowance\nHealth insurance\nAnnual bonus\nRelocation assistance', 'Kigali', 'Gasabo', 'Remera', 'Full-time', '3+ years', 'Bachelor\'s Degree', 700000, 1300000, '2026-09-15', 1, 'published'),
(6, 11, 'Programme Coordinator', 'programme-coordinator-sos', 'SOS Children''s Villages Rwanda is looking for a Programme Coordinator to manage and develop family-strengthening programs that support vulnerable children and families.', 'Coordinate programme activities across sites\nMonitor programme quality and impact\nManage budgets and resources\nBuild partnerships with stakeholders\nTrain and supervise programme staff\nPrepare programme reports', '4+ years of programme management experience in NGOs\nExperience in child protection or social work\nStrong project management skills\nExcellent written and verbal communication', 'Bachelor''s degree in Social Work, Development Studies, or related field\nMaster''s degree preferred\nExperience with international NGOs', 'Competitive NGO salary\nHealth insurance\nProfessional development\nAnnual leave\nMission opportunities', 'Kigali', 'Kicukiro', 'Kanombe', 'Full-time', '4+ years', 'Bachelor\'s Degree', 550000, 950000, '2026-08-25', 0, 'published'),
(7, 8, 'Agricultural Research Officer', 'agricultural-research-officer-rab', 'Rwanda Agricultural Board is recruiting Agricultural Research Officers to conduct research aimed at improving crop yields and farming practices in Rwanda.', 'Conduct field research on crop production\nCollect and analyze agricultural data\nDevelop improved farming techniques\nTrain farmers on best practices\nCollaborate with international research partners\nPublish research findings', '3+ years of agricultural research experience\nField work capability\nData analysis skills\nKnowledge of Rwandan agricultural systems', 'Bachelor''s degree in Agriculture or related field\nMaster''s degree preferred\nPublications in agricultural journals are a plus', 'Government salary scale\nResearch allowances\nField equipment provided\nConference attendance\nSabbatical opportunities', 'Southern', 'Huye', 'Huye Town', 'Full-time', '3+ years', 'Bachelor\'s Degree', 350000, 650000, '2026-09-10', 0, 'published'),
(8, 1, 'ICT Project Manager', 'ict-project-manager-risa', 'Rwanda Information Society Authority is looking for an ICT Project Manager to lead the implementation of digital transformation projects across government institutions.', 'Lead ICT project planning and execution\nManage project budgets and timelines\nCoordinate with government stakeholders\nOversee technical teams\nEnsure project quality standards\nReport on project progress', '5+ years of ICT project management experience\nPMP or PRINCE2 certification\nExperience with government IT projects\nStrong stakeholder management skills', 'Bachelor''s degree in IT or related field\nMaster''s degree preferred\nGovernment project experience required', 'Competitive salary\nHealth insurance\nTraining budget\nFlexible working\nAnnual bonus', 'Kigali', 'Gasabo', 'Kimihurura', 'Full-time', '5+ years', 'Bachelor\'s Degree', 900000, 1600000, '2026-09-30', 1, 'published'),
(2, 12, 'Finance Intern', 'finance-intern-bk', 'Bank of Kigali offers internship opportunities for recent graduates to gain practical experience in the banking and finance sector.', 'Assist with daily accounting tasks\nSupport financial report preparation\nHelp with data entry and reconciliation\nObserve banking operations\nComplete assigned projects\nParticipate in training sessions', 'Currently enrolled in or recently graduated from a relevant degree program\nStrong attention to detail\nProficiency in Microsoft Office\nEagerness to learn', 'Bachelor''s degree in Finance, Accounting, or related field (in progress or recently completed)\nStrong academic record', 'Monthly stipend\nMentorship program\nNetworking opportunities\nPotential for full-time employment\nProfessional development', 'Kigali', 'Nyarugenge', 'City Center', 'Internship', 'Entry Level', 'Bachelor\'s Degree', 150000, 250000, '2026-08-01', 0, 'published'),
(5, 13, 'Sales Executive', 'sales-executive-mtn', 'MTN Rwanda is hiring Sales Executives to drive subscriber growth and revenue through B2B and B2C sales activities across assigned territories.', 'Identify and pursue new business opportunities\nMeet monthly sales targets\nBuild and maintain client relationships\nConduct product demonstrations\nPrepare sales reports\nAttend industry events', '2+ years of sales experience preferably in telecom\nStrong negotiation skills\nSelf-motivated and target-driven\nValid driver''s license', 'Bachelor''s degree in Business, Marketing, or related field\nSales certifications are a plus', 'Competitive base salary plus commission\nHealth insurance\nPhone allowance\nPerformance bonuses\nCareer growth', 'Kigali', 'Gasabo', 'Nyabugogo', 'Full-time', '2+ years', 'Bachelor\'s Degree', 300000, 600000, '2026-08-10', 0, 'published');
